commands.command:
$ErrorActionPreference='Stop'
$runPath=Join-Path (Get-Location) '.tmp/1747-current-runtime-20261118b'
$ownedRows=Get-Content -LiteralPath (Join-Path $runPath 'owned-processes-before-private.json') -Raw | ConvertFrom-Json
$nextReceipt=Get-Content -LiteralPath (Join-Path $runPath 'next-process-private.json') -Raw | ConvertFrom-Json
$controllerReceipt=Get-Content -LiteralPath (Join-Path $runPath 'controller2-private.json') -Raw | ConvertFrom-Json
foreach($rootCheck in @(@{pid=$nextReceipt.parent;marker='1747-current-runtime-20261118b/runtime.mjs'},@{pid=$controllerReceipt.pid;marker='1747-current-runtime-20261118b/controller2.mjs'})){$rootProc=Get-CimInstance Win32_Process -Filter "ProcessId=$($rootCheck.pid)";if($rootProc -and ($rootProc.CommandLine.Replace('\','/') -notlike "*$($rootCheck.marker)*")){throw 'OWNED_ROOT_IDENTITY_REFUSAL'}}
$stopped=0;$alreadyGone=0
foreach($row in @($ownedRows | Sort-Object CreationDate -Descending)){$alive=Get-CimInstance Win32_Process -Filter "ProcessId=$($row.ProcessId)";if(!$alive){$alreadyGone++;continue};if($alive.ExecutablePath -ne $row.ExecutablePath -or $alive.CreationDate -ne [datetime]$row.CreationDate -or $alive.ParentProcessId -ne $row.ParentProcessId){throw 'PID_REUSE_OR_PARENT_REFUSAL'};Stop-Process -Id $alive.ProcessId -Force -ErrorAction Stop;$stopped++}
$remaining=@();foreach($row in $ownedRows){if(Get-CimInstance Win32_Process -Filter "ProcessId=$($row.ProcessId)"){$remaining+=$row.ProcessId}}
$profilePath=[System.IO.Path]::GetFullPath((Join-Path $runPath 'chromium-ephemeral'))
$allowedProfile=[System.IO.Path]::GetFullPath((Join-Path (Get-Location) '.tmp/1747-current-runtime-20261118b/chromium-ephemeral'))
if($profilePath -ne $allowedProfile -or !$profilePath.StartsWith([System.IO.Path]::GetFullPath($runPath)+[System.IO.Path]::DirectorySeparatorChar)){throw 'PROFILE_PATH_REFUSAL'}
if(Test-Path -LiteralPath $profilePath){$profileItem=Get-Item -LiteralPath $profilePath;if($profileItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint){throw 'PROFILE_REPARSE_REFUSAL'};Remove-Item -LiteralPath $profilePath -Recurse -Force}
@{stoppedExactProcesses=$stopped;alreadyExited=$alreadyGone;remainingOwnedProcesses=$remaining.Count;exactRootMarkersVerified=$true;creationExecutableParentVerified=$true;browserContextsClosed=$true;ephemeralProfileRemoved=!(Test-Path -LiteralPath $profilePath);noPeerCleanup=$true} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $runPath 'process-cleanup-SAFE.json')
Write-Output "EXACT_PROCESS_CLEANUP remaining=$($remaining.Count)"
